import{_ as e,o as a,c as s,a3 as n}from"./chunks/framework.CpLciM8b.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1785494959000}'),r={name:"guide/introduction.md"};function o(i,t,l,d,c,p){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Test tooling is stuck. Three systemic gaps:</p><ul><li><strong>Tests are report artifacts, not telemetry.</strong> JUnit XML and HTML reports capture <em>one</em> run — no history, no trace context, no correlation with application signals.</li><li><strong>Flaky detection is primitive.</strong> Most teams &quot;detect&quot; flakes by eyeballing <code>retries &gt; 0</code>. No stable identity across refactors, no statistical model, no auto-quarantine.</li><li><strong>Root-cause is manual archaeology.</strong> Every failure means digging through logs, stack traces, screenshots, and git blame — 20–40 minutes an incident.</li></ul><p>Flakemetry closes all three by modelling every test execution as an OpenTelemetry span.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Test observability</strong></td><td>Every run ingested as OTLP; full history per test, not per report</td></tr><tr><td><strong>Stable test identity</strong></td><td>Fingerprints that survive file moves, renames, and parameterization</td></tr><tr><td><strong>Explainable scoring</strong></td><td>A transparent Bayesian flaky score with human-readable reason codes</td></tr><tr><td><strong>AI root-cause</strong></td><td>Structured &quot;likely cause + suggested action&quot;, budget-gated, provider-agnostic</td></tr><tr><td><strong>CI-native</strong></td><td>GitHub Action + sticky PR comment; never blocks your build</td></tr><tr><td><strong>Self-hostable</strong></td><td>One <code>docker compose up</code>, MIT-licensed core</td></tr></tbody></table><h2 id="the-60-second-path" tabindex="-1">The 60-second path <a class="header-anchor" href="#the-60-second-path" aria-label="Permalink to &quot;The 60-second path&quot;">​</a></h2><ol><li><a href="/flakemetry/v/2026-09-30/guide/self-hosting"><strong>Self-host</strong></a> — <code>docker compose up</code> brings the whole stack up locally, seeded with demo runs.</li><li><a href="/flakemetry/v/2026-09-30/guide/reporters"><strong>Send a run</strong></a> — drop in a reporter, or upload <a href="/flakemetry/v/2026-09-30/guide/junit">JUnit XML from any runner</a>.</li><li><a href="/flakemetry/v/2026-09-30/guide/first-insight"><strong>Read your first insight</strong></a> — the flaky board ranks every test by a transparent score, worst first, with the reason codes behind it.</li></ol><h2 id="how-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to &quot;How it fits together&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> reporter / OTLP / GitHub Action</span></span>
<span class="line"><span>              │  OTLP-HTTP (JSON), idempotency-key</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>   Ingestion API (Fastify) ── validate + enqueue ─▶ 202 (never blocks CI)</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼   durable queue (Postgres SKIP LOCKED)</span></span>
<span class="line"><span>   Workers ── normalize ▶ test identity ▶ flaky scoring ▶ signature clustering ▶ AI RCA</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>   PostgreSQL (relational + JSONB + pgvector) · Object store (S3/MinIO)</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>   Query API (tRPC/REST) ─▶ Next.js dashboard  (runs · test history · flaky board · RCA)</span></span></code></pre></div><p>The write path returns <code>202</code> instantly and does the heavy work asynchronously — <strong>ingestion never blocks CI</strong>. See <a href="/flakemetry/v/2026-09-30/concepts/architecture">Architecture</a> for the full design.</p>`,11)])])}const g=e(r,[["render",o]]);export{u as __pageData,g as default};
